// optional array of more tree nodes. Expressed via $defs so the schema
// advertises strict properties with array items guidance.
const treeSchema = {
  $schema: 'https://json-schema.org/draft/2020-12/schema',
  $ref: '#/$defs/treeNode',
  $defs: {
    treeNode: {
      type: 'object',
      additionalProperties: false,
      properties: {
        value: { type: 'integer' },
        children: {
          type: 'array',
          items: { $ref: '#/$defs/treeNode' }
        }
      },
      required: ['value']
    }
  }
};

class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.code = -32602;
  }
}

const tools = [
  {
    name: 'tree_sum',
    description:
      'Recursively sum the integer values of a tree. Each node has an integer "value" and an optional "children" array of more tree nodes.',
    inputSchema: treeSchema
  }
